const repo = "acme/web";
const asArray = (r: any): any[] => {
  if (Array.isArray(r)) return r;
  if (r && Array.isArray(r.items)) return r.items;
  if (r && Array.isArray(r.issues)) return r.issues;
  if (r && Array.isArray(r.comments)) return r.comments;
  if (r && Array.isArray(r.data)) return r.data;
  return [];
};
const loginOf = (c: any): string | undefined =>
  c?.user?.login ?? c?.author?.login ?? c?.login ?? (typeof c?.user === "string" ? c.user : undefined) ?? (typeof c?.author === "string" ? c.author : undefined);

// 1. All open issues labeled perf (paginate)
const issues: any[] = [];
const seenIssue = new Set<number>();
for (let page = 1; page < 100; page++) {
  const batch = asArray(await tools.list_issues({ repo, state: "open", label: "perf", page }));
  if (batch.length === 0) break;
  let added = 0;
  for (const i of batch) {
    const n = i.number;
    if (!seenIssue.has(n)) { seenIssue.add(n); issues.push(i); added++; }
  }
  if (added === 0) break;
}

// 2. For each issue, collect distinct commenters (paginate comments)
const commenters = new Map<string, Set<number>>();
const perIssue: Record<number, string[]> = {};
for (const issue of issues) {
  const num = issue.number;
  const users = new Set<string>();
  for (let page = 1; page < 100; page++) {
    const batch = asArray(await tools.list_comments({ repo, number: num, page }));
    if (batch.length === 0) break;
    for (const c of batch) {
      const login = loginOf(c);
      if (login) users.add(login);
    }
    if (batch.length < 50) break;
  }
  perIssue[num] = [...users];
  for (const u of users) {
    if (!commenters.has(u)) commenters.set(u, new Set());
    commenters.get(u)!.add(num);
  }
}

const result = [...commenters.entries()]
  .filter(([, s]) => s.size >= 4)
  .map(([login, s]) => ({ login, issues: [...s].sort((a, b) => a - b) }))
  .sort((a, b) => a.login.localeCompare(b.login));

console.log(JSON.stringify({ openPerfIssues: issues.map(i => i.number), perIssue, result }, null, 2));
return result.map(r => r.login);
